// Digest calls main/digest (async: it answers a job; Wait for the output).
func (d *ShelfMain) Digest(ctx context.Context, in FnMainDigestInput, opts ...client.RequestOption) (*client.Job, error) {
	return d.db.Call(ctx, "digest", in, nil, append([]client.RequestOption{client.WithRespondAsync()}, opts...)...)
}

// Download calls main/download.
func (d *ShelfMain) Download(ctx context.Context, in FnMainDownloadInput, opts ...client.RequestOption) (*json.RawMessage, error) {
	var out json.RawMessage
	if _, err := d.db.Call(ctx, "download", in, &out, opts...); err != nil {
		return nil, err
	}
	return &out, nil
}

