// LoadConfig reads the realm's app configuration, as the caller sees it.
func (r *ShelfRealm) LoadConfig(ctx context.Context, opts ...client.RequestOption) (*ShelfConfigTree, error) {
	values, err := r.Client.Config().Load(ctx, nil, opts...)
	if err != nil {
		return nil, err
	}
	raw, err := json.Marshal(values)
	if err != nil {
		return nil, err
	}
	var out ShelfConfigTree
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, err
	}
	return &out, nil
}
